begin;
create table public.billing_rate_cards (
 id uuid primary key default gen_random_uuid(),version bigint generated by default as identity unique,
 currency text not null check(currency='JMD'),rates_cents jsonb not null,
 rounding text not null check(rounding='ceil_lb'),status text not null check(status in ('draft','approved','published')),
 effective_at timestamptz not null,approval_reference text,created_at timestamptz not null default now(),approved_at timestamptz
);
insert into public.billing_rate_cards(currency,rates_cents,rounding,status,effective_at,approval_reference,approved_at)
 values('JMD','[69500,109500,139500,169500,199500,229500,259500,289500,319500,349500]','ceil_lb','approved','2026-10-20T00:00:00-05:00','Owner instruction, project chat 2026-10-20: supplied shipping table and costs',now());
create table public.billing_manual_quotes(id uuid primary key default gen_random_uuid(),package_id uuid not null references public.packages(id),weight_lb numeric(10,3) not null check(weight_lb>10),amount_cents bigint not null check(amount_cents>0 and amount_cents<=99999999999),evidence text not null,approved_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create index billing_quotes_package on public.billing_manual_quotes(package_id);
create table public.billing_invoices (
 id uuid primary key default gen_random_uuid(),number bigint generated by default as identity unique,package_id uuid not null references public.packages(id),profile_id uuid not null references public.profiles(id),tracking text not null,
 status text not null default 'draft' check(status in ('draft','issued','disputed','void')),
 currency text not null default 'JMD' check(currency='JMD'),weight_lb numeric(10,3) not null,billable_lb integer not null,
 rate_snapshot jsonb not null,lines jsonb not null,total_cents bigint not null check(total_cents>0 and total_cents<=99999999999),
 adjustment_cents bigint not null default 0,received_cents bigint not null default 0 check(received_cents>=0),
 balance_cents bigint generated always as(total_cents+adjustment_cents-received_cents) stored check(balance_cents>=0),
 payment_status text not null default 'unpaid' check(payment_status in('unpaid','partially_paid','paid')),
 version integer not null default 1,due_at timestamptz,issued_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index billing_one_active_invoice on public.billing_invoices(package_id)where status<>'void';
create index billing_invoices_customer on public.billing_invoices(profile_id,created_at desc,id);
create table private.billing_assessments(invoice_id uuid primary key references public.billing_invoices(id),reference text not null,actor_id uuid not null references public.profiles(id));
alter table private.billing_assessments enable row level security;revoke all on private.billing_assessments from public,anon,authenticated,service_role;
create table public.billing_payments(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.billing_invoices(id),kind text not null check(kind in('receipt','reversal')),amount_cents bigint not null check(amount_cents>0 and amount_cents<=99999999999),channel text not null,reference text not null,reverses_id uuid unique references public.billing_payments(id),actor_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(channel,reference),check((kind='reversal')=(reverses_id is not null)));
create table private.billing_payment_evidence(payment_id uuid primary key references public.billing_payments(id),evidence text not null);
alter table private.billing_payment_evidence enable row level security;revoke all on private.billing_payment_evidence from public,anon,authenticated,service_role;
create index billing_payments_invoice on public.billing_payments(invoice_id,created_at,id);create index billing_payments_actor on public.billing_payments(actor_id);
create table public.billing_adjustments(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.billing_invoices(id),kind text not null check(kind in('shipping','duties_tax','handling','local_delivery','storage')),amount_cents bigint not null check(amount_cents<>0 and abs(amount_cents)<=99999999999),description text not null,actor_id uuid not null references public.profiles(id),created_at timestamptz not null default now());
create index billing_adjustments_invoice on public.billing_adjustments(invoice_id,created_at,id);create index billing_adjustments_actor on public.billing_adjustments(actor_id);
create table public.billing_history(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.billing_invoices(id),action text not null,message text not null,created_at timestamptz not null default now());create index billing_history_invoice on public.billing_history(invoice_id,created_at,id);
create table public.billing_cost_records(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.billing_invoices(id),revision integer not null,amounts_jmd_cents jsonb not null,evidence text not null,actor_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(invoice_id,revision));create index billing_cost_actor on public.billing_cost_records(actor_id);
create table public.billing_outbox(id uuid primary key default gen_random_uuid(),history_id uuid not null unique references public.billing_history(id),state text not null default 'deferred' check(state='deferred'),created_at timestamptz not null default now());
create function private.billing_payment_proofs(p_invoice uuid)returns table(payment_id uuid,evidence text)language plpgsql security definer set search_path='' as $$begin
 if not private.has_role(array['owner','finance'])then raise exception 'Finance role required';end if;
 return query select p.id,e.evidence from public.billing_payments p join private.billing_payment_evidence e on e.payment_id=p.id where p.invoice_id=p_invoice;
end$$;
create function public.billing_payment_proofs(p_invoice uuid)returns table(payment_id uuid,evidence text)language sql security invoker set search_path='' as $$select * from private.billing_payment_proofs(p_invoice)$$;
revoke all on function private.billing_payment_proofs(uuid),public.billing_payment_proofs(uuid) from public,anon,service_role;
grant execute on function private.billing_payment_proofs(uuid),public.billing_payment_proofs(uuid) to authenticated;
-- Staff mutation uses only private checked functions; no browser/service-role table writes.
alter table public.billing_rate_cards enable row level security;revoke all on public.billing_rate_cards from public,anon,authenticated,service_role;
alter table public.billing_manual_quotes enable row level security;revoke all on public.billing_manual_quotes from public,anon,authenticated,service_role;
alter table public.billing_invoices enable row level security;revoke all on public.billing_invoices from public,anon,authenticated,service_role;
alter table public.billing_payments enable row level security;revoke all on public.billing_payments from public,anon,authenticated,service_role;
alter table public.billing_adjustments enable row level security;revoke all on public.billing_adjustments from public,anon,authenticated,service_role;
alter table public.billing_history enable row level security;revoke all on public.billing_history from public,anon,authenticated,service_role;
alter table public.billing_cost_records enable row level security;revoke all on public.billing_cost_records from public,anon,authenticated,service_role;
alter table public.billing_outbox enable row level security;revoke all on public.billing_outbox from public,anon,authenticated,service_role;
grant select on public.billing_rate_cards,public.billing_manual_quotes,public.billing_invoices,public.billing_payments,public.billing_adjustments,public.billing_history,public.billing_cost_records to authenticated;
create policy billing_rates_read on public.billing_rate_cards for select to authenticated using(private.has_role(array['owner','finance']));
create policy billing_quotes_read on public.billing_manual_quotes for select to authenticated using(private.has_role(array['owner','finance']));
create policy billing_invoice_read on public.billing_invoices for select to authenticated using((profile_id=(select auth.uid()) and status<>'draft' and (select private.active_customer())) or (select private.has_role(array['owner','finance','operations'])));
create policy billing_payments_read on public.billing_payments for select to authenticated using((select private.has_role(array['owner','finance'])) or exists(select 1 from public.billing_invoices i where i.id=invoice_id and i.profile_id=(select auth.uid())));
create policy billing_adjustments_read on public.billing_adjustments for select to authenticated using(exists(select 1 from public.billing_invoices i where i.id=invoice_id));
create policy billing_history_read on public.billing_history for select to authenticated using(exists(select 1 from public.billing_invoices i where i.id=invoice_id));
create policy billing_cost_read on public.billing_cost_records for select to authenticated using(private.has_role(array['owner','finance']));
create function private.billing_invoice_guard()returns trigger language plpgsql security invoker set search_path='' as $$begin
 if old.status<>'draft' and (new.lines is distinct from old.lines or new.total_cents<>old.total_cents or new.rate_snapshot is distinct from old.rate_snapshot or new.weight_lb<>old.weight_lb or new.billable_lb<>old.billable_lb or new.package_id<>old.package_id or new.profile_id<>old.profile_id or new.tracking<>old.tracking or new.currency<>old.currency)then raise exception 'Issued invoice contents are immutable; append an adjustment';end if;return new;end $$;
revoke all on function private.billing_invoice_guard() from public,anon,authenticated,service_role;
create trigger billing_invoice_guard before update on public.billing_invoices for each row execute function private.billing_invoice_guard();
create function private.billing_history_add(p_invoice uuid,p_action text,p_message text,p_reason text)returns void language plpgsql security definer set search_path='' as $$declare h uuid;begin
 insert into public.billing_history(invoice_id,action,message)values(p_invoice,p_action,p_message)returning id into h;
 insert into public.billing_outbox(history_id)values(h);
 insert into public.audit_logs(actor_id,entity_type,entity_id,action,after_data,reason)values(auth.uid(),'invoice',p_invoice,p_action,jsonb_build_object('history_id',h),p_reason);
end $$;
create function private.billing_lock(p_id uuid,p_version integer)returns public.billing_invoices language plpgsql security definer set search_path='' as $$declare i public.billing_invoices;begin
 if not private.has_role(array['owner','finance'])then raise exception 'Finance role required';end if;
 perform 1 from public.profiles where id=(select profile_id from public.billing_invoices where id=p_id)for update;
 perform 1 from public.packages where id=(select package_id from public.billing_invoices where id=p_id)for update;
 select * into i from public.billing_invoices where id=p_id for update;
 if i.id is null or i.version is distinct from p_version then raise exception 'Invoice changed or unavailable; refresh';end if;return i;end $$;
create function private.refresh_invoice(p_id uuid)returns void language plpgsql security definer set search_path='' as $$declare i public.billing_invoices;a bigint;r bigint;begin
 select * into i from public.billing_invoices where id=p_id;
 select coalesce(sum(amount_cents),0)into a from public.billing_adjustments where invoice_id=p_id;
 select coalesce(sum(case when kind='receipt' then amount_cents else -amount_cents end),0)into r from public.billing_payments where invoice_id=p_id;
 if i.total_cents+a>99999999999 then raise exception 'Adjusted total exceeds limit';end if;
 if r<0 or i.total_cents+a<r then raise exception 'Credit exceeds unpaid balance; settle refund separately';end if;
 update public.billing_invoices set adjustment_cents=a,received_cents=r,payment_status=case when total_cents+a=r then 'paid' when r>0 then 'partially_paid' else 'unpaid' end,version=version+1,updated_at=now()where id=p_id;
 update public.packages set payment_state=case when i.status in('draft','void')then 'not_invoiced' when i.status='disputed'then 'disputed' when i.total_cents+a=r then 'paid' when r>0 then 'partially_paid' else 'unpaid'end where id=i.package_id;
end $$;
revoke all on function private.billing_history_add(uuid,text,text,text),private.billing_lock(uuid,integer),private.refresh_invoice(uuid) from public,anon,authenticated,service_role;
alter table public.packages drop constraint packages_payment_state_check;
alter table public.packages add constraint packages_payment_state_check check(payment_state in('not_invoiced','unpaid','partially_paid','paid','disputed'));
create function private.create_billing_invoice(p_package uuid,p_weight numeric,p_extras jsonb,p_evidence text,p_due timestamptz)returns uuid language plpgsql security definer set search_path='' as $$
declare p public.packages;rate public.billing_rate_cards;q public.billing_manual_quotes;w integer;shipping bigint;total bigint;item jsonb;lines jsonb;result uuid;kind text;
begin
 if not private.has_role(array['owner','finance'])then raise exception 'Finance role required';end if;
 if p_weight is null or p_weight<=0 or p_weight>50000 or p_weight<>round(p_weight,3) or p_evidence is null or length(trim(p_evidence))not between 5 and 2000 or (p_due is not null and not isfinite(p_due))then raise exception 'Verified weight and charge assessment required';end if;
 perform 1 from public.profiles where id=(select profile_id from public.packages where id=p_package)for update;
 select * into p from public.packages where id=p_package for update;if p.id is null or p.status in('cancelled','returned','delivered')then raise exception 'Package unavailable for billing';end if;
 if exists(select 1 from public.billing_invoices where package_id=p.id and status<>'void')then raise exception 'An active invoice already exists';end if;
 w:=ceil(p_weight);select * into rate from public.billing_rate_cards where status in('approved','published')and effective_at<=now()order by effective_at desc,version desc limit 1;
 if rate.id is null then raise exception 'Approved rate card required';end if;
 if w<=10 then shipping:=(rate.rates_cents->>(w-1))::bigint;else
 select * into q from public.billing_manual_quotes where package_id=p.id and weight_lb=p_weight order by created_at desc,id desc limit 1;
 if q.id is null then raise exception 'Owner-approved manual quote required above 10 lb';end if;shipping:=q.amount_cents;end if;
 if jsonb_typeof(p_extras)is distinct from 'object' or (select count(*)from jsonb_object_keys(p_extras))<>4 then raise exception 'Explicit assessed extras required';end if;
 lines:=jsonb_build_array(jsonb_build_object('kind','shipping','description','Approved shipping charge','amount_cents',shipping));total:=shipping;
 foreach kind in array array['duties_tax','handling','local_delivery','storage']loop
 item:=p_extras->kind;if jsonb_typeof(item)is distinct from 'number' or (item::text)::numeric<>trunc((item::text)::numeric)or (item::text)::numeric<0 or (item::text)::numeric>99999999999 then raise exception 'Each extra must be an explicit non-negative JMD cent amount';end if;
 lines:=lines||jsonb_build_array(jsonb_build_object('kind',kind,'description',replace(kind,'_',' '),'amount_cents',(item::text)::bigint));total:=total+(item::text)::bigint;end loop;
 insert into public.billing_invoices(package_id,profile_id,tracking,weight_lb,billable_lb,rate_snapshot,lines,total_cents,due_at)values(p.id,p.profile_id,p.carrier_tracking,p_weight,w,jsonb_build_object('id',rate.id,'version',rate.version,'rounding',rate.rounding,'currency',rate.currency,'shipping_cents',shipping,'quote_id',q.id,'approval',rate.approval_reference),lines,total,p_due)returning id into result;
 insert into private.billing_assessments values(result,p_evidence,auth.uid());
 perform private.billing_history_add(result,'invoice_drafted','Invoice prepared for staff review.','Verified assessment: '||p_evidence);return result;
end
$$;
create function public.create_billing_invoice(p_package uuid,p_weight numeric,p_extras jsonb,p_evidence text,p_due timestamptz)returns uuid language sql security invoker set search_path='' as $$select private.create_billing_invoice(p_package,p_weight,p_extras,p_evidence,p_due)$$;
revoke all on function private.create_billing_invoice(uuid,numeric,jsonb,text,timestamptz),public.create_billing_invoice(uuid,numeric,jsonb,text,timestamptz) from public,anon,service_role;grant execute on function private.create_billing_invoice(uuid,numeric,jsonb,text,timestamptz),public.create_billing_invoice(uuid,numeric,jsonb,text,timestamptz) to authenticated;
create function private.approve_billing_quote(p_package uuid,p_weight numeric,p_amount bigint,p_evidence text)returns uuid language plpgsql security definer set search_path='' as $$
declare result uuid;begin
 if not private.has_role(array['owner'])then raise exception 'Owner approval required';end if;
 if p_weight is null or p_weight<=10 or p_weight>50000 or p_weight<>round(p_weight,3)or p_amount is null or p_amount<=0 or p_amount>99999999999 or p_evidence is null or length(trim(p_evidence))not between 5 and 2000 then raise exception 'Valid manual quote and evidence required';end if;
 insert into public.billing_manual_quotes(package_id,weight_lb,amount_cents,evidence,approved_by)values(p_package,p_weight,p_amount,p_evidence,auth.uid())returning id into result;
 insert into public.audit_logs(actor_id,entity_type,entity_id,action,after_data,reason)values(auth.uid(),'quote',result,'manual_quote_approved',jsonb_build_object('package_id',p_package,'weight_lb',p_weight,'amount_cents',p_amount),p_evidence);return result;end
$$;
create function public.approve_billing_quote(p_package uuid,p_weight numeric,p_amount bigint,p_evidence text)returns uuid language sql security invoker set search_path='' as $$select private.approve_billing_quote(p_package,p_weight,p_amount,p_evidence)$$;
revoke all on function private.approve_billing_quote(uuid,numeric,bigint,text),public.approve_billing_quote(uuid,numeric,bigint,text) from public,anon,service_role;grant execute on function private.approve_billing_quote(uuid,numeric,bigint,text),public.approve_billing_quote(uuid,numeric,bigint,text) to authenticated;
create function private.change_billing_invoice(p_id uuid,p_version integer,p_action text,p_message text,p_reason text)returns void language plpgsql security definer set search_path='' as $$
declare i public.billing_invoices;new_status text;begin
i:=private.billing_lock(p_id,p_version);
if p_reason is null or length(trim(p_reason))not between 5 and 2000 or p_message is null or length(trim(p_message))not between 5 and 1000 then raise exception 'Customer explanation and internal reason required';end if;
new_status:=case when p_action='issue'and i.status='draft'then 'issued' when p_action='dispute'and i.status='issued'then 'disputed'when p_action='resolve_dispute'and i.status='disputed'then 'issued'when p_action='void'and i.status in('draft','issued','disputed')and i.received_cents=0 and i.adjustment_cents=0 then 'void'else null end;
if new_status is null then raise exception 'Invalid invoice action or financial records prevent voiding';end if;
if exists(select 1 from public.packages where id=i.package_id and status in('ready_for_pickup','out_for_delivery','delivered'))and new_status='void'then raise exception 'Cannot void a released invoice';end if;
update public.billing_invoices set status=new_status,issued_at=case when p_action='issue'then now()else issued_at end where id=p_id;
perform private.refresh_invoice(p_id);perform private.billing_history_add(p_id,'invoice_'||p_action,p_message,p_reason);end
$$;
create function public.change_billing_invoice(p_id uuid,p_version integer,p_action text,p_message text,p_reason text)returns void language sql security invoker set search_path='' as $$select private.change_billing_invoice(p_id,p_version,p_action,p_message,p_reason)$$;
revoke all on function private.change_billing_invoice(uuid,integer,text,text,text),public.change_billing_invoice(uuid,integer,text,text,text) from public,anon,service_role;grant execute on function private.change_billing_invoice(uuid,integer,text,text,text),public.change_billing_invoice(uuid,integer,text,text,text) to authenticated;
create function private.record_billing_payment(p_id uuid,p_version integer,p_amount bigint,p_channel text,p_reference text,p_evidence text,p_reason text)returns uuid language plpgsql security definer set search_path='' as $$
declare i public.billing_invoices;existing public.billing_payments;result uuid;begin
i:=private.billing_lock(p_id,p_version);
if i.status not in('issued','disputed')or p_amount is null or p_amount<=0 or p_amount>i.balance_cents or p_channel is null or length(trim(p_channel))not between 2 and 80 or p_reference is null or length(trim(p_reference))not between 3 and 160 or p_evidence is null or length(trim(p_evidence))not between 5 and 1000 or p_reason is null or length(trim(p_reason))not between 5 and 2000 then raise exception 'Valid verified payment within outstanding balance required';end if;
-- Unique normalized channel/reference prevents double allocation across invoices.
select * into existing from public.billing_payments where channel=lower(trim(p_channel))and reference=trim(p_reference);
if existing.id is not null then raise exception 'Payment reference already recorded';end if;
insert into public.billing_payments(invoice_id,kind,amount_cents,channel,reference,actor_id)values(p_id,'receipt',p_amount,lower(trim(p_channel)),trim(p_reference),auth.uid())returning id into result;
insert into private.billing_payment_evidence values(result,p_evidence);
perform private.refresh_invoice(p_id);perform private.billing_history_add(p_id,'payment_verified','Payment of JMD '||(p_amount::numeric/100)::text||' verified.',p_reason);return result;end
$$;
create function public.record_billing_payment(p_id uuid,p_version integer,p_amount bigint,p_channel text,p_reference text,p_evidence text,p_reason text)returns uuid language sql security invoker set search_path='' as $$select private.record_billing_payment(p_id,p_version,p_amount,p_channel,p_reference,p_evidence,p_reason)$$;
revoke all on function private.record_billing_payment(uuid,integer,bigint,text,text,text,text),public.record_billing_payment(uuid,integer,bigint,text,text,text,text) from public,anon,service_role;grant execute on function private.record_billing_payment(uuid,integer,bigint,text,text,text,text),public.record_billing_payment(uuid,integer,bigint,text,text,text,text) to authenticated;
create function private.reverse_billing_payment(p_id uuid,p_version integer,p_payment uuid,p_reference text,p_evidence text,p_reason text)returns uuid language plpgsql security definer set search_path='' as $$
declare i public.billing_invoices;r public.billing_payments;result uuid;begin
i:=private.billing_lock(p_id,p_version);
select * into r from public.billing_payments where id=p_payment and invoice_id=p_id and kind='receipt';
if r.id is null or i.status not in('issued','disputed')or exists(select 1 from public.billing_payments where reverses_id=r.id)or p_reference is null or length(trim(p_reference))not between 3 and 160 or p_evidence is null or length(trim(p_evidence))not between 5 and 1000 or p_reason is null or length(trim(p_reason))not between 5 and 2000 then raise exception 'Unreversed payment and reversal evidence required';end if;
insert into public.billing_payments(invoice_id,kind,amount_cents,channel,reference,reverses_id,actor_id)values(p_id,'reversal',r.amount_cents,r.channel,trim(p_reference),r.id,auth.uid())returning id into result;
insert into private.billing_payment_evidence values(result,p_evidence);
perform private.refresh_invoice(p_id);perform private.billing_history_add(p_id,'payment_reversed','A previously verified payment was reversed. Review your balance.',p_reason);return result;end
$$;
create function public.reverse_billing_payment(p_id uuid,p_version integer,p_payment uuid,p_reference text,p_evidence text,p_reason text)returns uuid language sql security invoker set search_path='' as $$select private.reverse_billing_payment(p_id,p_version,p_payment,p_reference,p_evidence,p_reason)$$;
revoke all on function private.reverse_billing_payment(uuid,integer,uuid,text,text,text),public.reverse_billing_payment(uuid,integer,uuid,text,text,text) from public,anon,service_role;grant execute on function private.reverse_billing_payment(uuid,integer,uuid,text,text,text),public.reverse_billing_payment(uuid,integer,uuid,text,text,text) to authenticated;
create function private.adjust_billing_invoice(p_id uuid,p_version integer,p_kind text,p_amount bigint,p_description text,p_reason text)returns uuid language plpgsql security definer set search_path='' as $$
declare i public.billing_invoices;result uuid;begin
i:=private.billing_lock(p_id,p_version);
if p_amount<0 and not private.has_role(array['owner'])then raise exception 'Credits require owner approval';end if;
if i.status not in('issued','disputed')or p_kind is null or p_kind not in('shipping','duties_tax','handling','local_delivery','storage')or p_amount is null or p_amount=0 or abs(p_amount)>99999999999 or p_description is null or length(trim(p_description))not between 5 and 500 or p_reason is null or length(trim(p_reason))not between 5 and 2000 then raise exception 'Valid adjustment required';end if;
if coalesce((select sum((v->>'amount_cents')::bigint)from jsonb_array_elements(i.lines)v where v->>'kind'=p_kind),0)+coalesce((select sum(amount_cents)from public.billing_adjustments where invoice_id=p_id and kind=p_kind),0)+p_amount<0 then raise exception 'Credit exceeds assessed category charge';end if;
insert into public.billing_adjustments(invoice_id,kind,amount_cents,description,actor_id)values(p_id,p_kind,p_amount,p_description,auth.uid())returning id into result;
perform private.refresh_invoice(p_id);perform private.billing_history_add(p_id,'invoice_adjusted',p_description,p_reason);return result;end
$$;
create function public.adjust_billing_invoice(p_id uuid,p_version integer,p_kind text,p_amount bigint,p_description text,p_reason text)returns uuid language sql security invoker set search_path='' as $$select private.adjust_billing_invoice(p_id,p_version,p_kind,p_amount,p_description,p_reason)$$;
revoke all on function private.adjust_billing_invoice(uuid,integer,text,bigint,text,text),public.adjust_billing_invoice(uuid,integer,text,bigint,text,text) from public,anon,service_role;grant execute on function private.adjust_billing_invoice(uuid,integer,text,bigint,text,text),public.adjust_billing_invoice(uuid,integer,text,bigint,text,text) to authenticated;
create function private.record_billing_costs(p_id uuid,p_version integer,p_costs jsonb,p_evidence text)returns void language plpgsql security definer set search_path='' as $$
declare i public.billing_invoices;k text;v jsonb;n integer;begin
i:=private.billing_lock(p_id,p_version);
if jsonb_typeof(p_costs)is distinct from 'object'or (select count(*)from jsonb_object_keys(p_costs))<>6 or p_evidence is null or length(trim(p_evidence))not between 5 and 2000 then raise exception 'Explicit actual cost inputs and source required';end if;
foreach k in array array['freight','receiving','consolidation','payment','last_mile','other']loop v:=p_costs->k;if v is null or (v<>'null'::jsonb and (jsonb_typeof(v)<>'number'or(v::text)::numeric<0 or(v::text)::numeric<>trunc((v::text)::numeric)or(v::text)::numeric>99999999999))then raise exception 'Costs must be known non-negative JMD cents or explicit unknown null';end if;end loop;
select coalesce(max(revision),0)+1 into n from public.billing_cost_records where invoice_id=p_id;
insert into public.billing_cost_records(invoice_id,revision,amounts_jmd_cents,evidence,actor_id)values(p_id,n,p_costs,p_evidence,auth.uid());
update public.billing_invoices set version=version+1,updated_at=now()where id=p_id;
insert into public.audit_logs(actor_id,entity_type,entity_id,action,after_data,reason)values(auth.uid(),'invoice',p_id,'actual_costs_recorded',jsonb_build_object('revision',n),p_evidence);end
$$;
create function public.record_billing_costs(p_id uuid,p_version integer,p_costs jsonb,p_evidence text)returns void language sql security invoker set search_path='' as $$select private.record_billing_costs(p_id,p_version,p_costs,p_evidence)$$;
revoke all on function private.record_billing_costs(uuid,integer,jsonb,text),public.record_billing_costs(uuid,integer,jsonb,text) from public,anon,service_role;grant execute on function private.record_billing_costs(uuid,integer,jsonb,text),public.record_billing_costs(uuid,integer,jsonb,text) to authenticated;
create function private.create_billing_rate(p_rates jsonb,p_effective timestamptz,p_reason text)returns uuid language plpgsql security definer set search_path='' as $$
declare v jsonb;result uuid;begin
if not private.has_role(array['owner','finance'])then raise exception 'Finance role required';end if;
if jsonb_typeof(p_rates)is distinct from 'array'or jsonb_array_length(p_rates)<>10 or p_effective is null or not isfinite(p_effective)or p_reason is null or length(trim(p_reason))not between 5 and 2000 then raise exception 'Ten prices and effective date required';end if;
for v in select value from jsonb_array_elements(p_rates)loop if jsonb_typeof(v)<>'number'or(v::text)::numeric<=0 or(v::text)::numeric<>trunc((v::text)::numeric)or(v::text)::numeric>99999999999 then raise exception 'Prices must be positive integer JMD cents';end if;end loop;
insert into public.billing_rate_cards(currency,rates_cents,rounding,status,effective_at,approval_reference)values('JMD',p_rates,'ceil_lb','draft',p_effective,p_reason)returning id into result;
insert into public.audit_logs(actor_id,entity_type,entity_id,action,after_data,reason)values(auth.uid(),'rate',result,'rate_drafted',jsonb_build_object('rates_cents',p_rates,'effective_at',p_effective),p_reason);return result;end
$$;
create function public.create_billing_rate(p_rates jsonb,p_effective timestamptz,p_reason text)returns uuid language sql security invoker set search_path='' as $$select private.create_billing_rate(p_rates,p_effective,p_reason)$$;
revoke all on function private.create_billing_rate(jsonb,timestamptz,text),public.create_billing_rate(jsonb,timestamptz,text) from public,anon,service_role;grant execute on function private.create_billing_rate(jsonb,timestamptz,text),public.create_billing_rate(jsonb,timestamptz,text) to authenticated;
create function private.approve_billing_rate(p_id uuid,p_reason text)returns void language plpgsql security definer set search_path='' as $$
begin
if not private.has_role(array['owner'])then raise exception 'Owner approval required';end if;
if p_reason is null or length(trim(p_reason))not between 5 and 2000 then raise exception 'Approval reference required';end if;
update public.billing_rate_cards set status='approved',approved_at=now(),approval_reference=p_reason where id=p_id and status='draft';if not found then raise exception 'Rate changed or unavailable';end if;
insert into public.audit_logs(actor_id,entity_type,entity_id,action,after_data,reason)values(auth.uid(),'rate',p_id,'rate_approved','{"status":"approved"}',p_reason);end
$$;
create function public.approve_billing_rate(p_id uuid,p_reason text)returns void language sql security invoker set search_path='' as $$select private.approve_billing_rate(p_id,p_reason)$$;
revoke all on function private.approve_billing_rate(uuid,text),public.approve_billing_rate(uuid,text) from public,anon,service_role;grant execute on function private.approve_billing_rate(uuid,text),public.approve_billing_rate(uuid,text) to authenticated;
alter table public.packages drop constraint packages_status_check;
alter table public.packages add constraint packages_status_check check(status in('pre_alerted','received_us','processing_us','in_transit','arrived_jm','customs_processing','customs_hold','cleared','ready_for_pickup','out_for_delivery','delivered','exception','returned','cancelled'));
alter table public.packages add column resume_status text;
create table public.shipment_release_checks(id uuid primary key default gen_random_uuid(),package_id uuid not null references public.packages(id),event_id uuid not null unique references public.package_events(id),invoice_id uuid not null references public.billing_invoices(id),invoice_version integer not null,document_count integer not null,evidence text not null,actor_id uuid not null references public.profiles(id),created_at timestamptz not null default now());
create index shipment_release_package on public.shipment_release_checks(package_id);create index shipment_release_invoice on public.shipment_release_checks(invoice_id);create index shipment_release_actor on public.shipment_release_checks(actor_id);
alter table public.shipment_release_checks enable row level security;revoke all on public.shipment_release_checks from public,anon,authenticated,service_role;grant select on public.shipment_release_checks to authenticated;
create policy release_checks_read on public.shipment_release_checks for select to authenticated using(private.has_role(array['owner','operations','finance']));
create or replace function private.record_package_event(p_package uuid,p_expected text,p_status text,p_source text,p_reason text,p_occurred timestamptz)returns uuid language plpgsql security definer set search_path='' as $$
declare p public.packages;i public.billing_invoices;result uuid;ok boolean:=false;docs integer;
begin
if not private.has_role(array['owner','operations'])then raise exception 'Access denied';end if;
if p_occurred is null or not isfinite(p_occurred)or p_occurred>now()or p_occurred<now()-interval '1 year'or p_source is null or length(trim(p_source))not between 5 and 500 or p_reason is null or length(trim(p_reason))not between 5 and 2000 then raise exception 'Evidence, effective time and reason required';end if;
perform 1 from public.profiles where id=(select profile_id from public.packages where id=p_package)for update;
select * into p from public.packages where id=p_package for update;
if p.id is null or p.status is distinct from p_expected then raise exception 'Record changed or unavailable';end if;
ok:=case p.status when 'pre_alerted'then p_status in('received_us','cancelled')when 'received_us'then p_status='processing_us'when 'processing_us'then p_status='in_transit'when 'in_transit'then p_status='arrived_jm'when 'arrived_jm'then p_status='customs_processing'when 'customs_processing'then p_status in('customs_hold','cleared')when 'customs_hold'then p_status in('customs_processing','cleared')when 'cleared'then p_status='ready_for_pickup'when 'ready_for_pickup'then p_status in('out_for_delivery','delivered')when 'out_for_delivery'then p_status='delivered'when 'exception'then p_status=p.resume_status else false end;
if p.status not in('delivered','returned','cancelled','pre_alerted','exception')and p_status='exception'then ok:=true;end if;
if p.status not in('delivered','returned','cancelled','pre_alerted')and p_status='returned'and private.has_role(array['owner'])then ok:=true;end if;
if not coalesce(ok,false)then raise exception 'Invalid shipment transition';end if;
if p_occurred<(select occurred_at from public.package_events where package_id=p.id order by sequence desc limit 1)then raise exception 'Event time precedes latest evidence';end if;
if p_status in('ready_for_pickup','out_for_delivery','delivered')then
 select * into i from public.billing_invoices where package_id=p.id and status<>'void'for update;
 if i.id is null or i.status<>'issued'or i.balance_cents<>0 then raise exception 'An issued, undisputed and fully settled invoice is required';end if;
 if not exists(select 1 from public.shipping_accounts a join public.warehouses w on w.id=a.warehouse_id where a.profile_id=p.profile_id and a.status='active'and w.active and w.verified_at is not null)or not exists(select 1 from public.profiles where id=p.profile_id and account_status='active')then raise exception 'Active customer and verified shipping assignment required';end if;
 -- Lock the subject to serialize new profile-level requirements against release.
 perform 1 from public.profiles where id=p.profile_id for update;
 if exists(select 1 from public.document_requests d where d.profile_id=p.profile_id and(d.package_id=p.id or d.package_id is null)and d.status not in('approved','waived'))then raise exception 'Outstanding documents prevent release';end if;
 select count(*)into docs from public.document_requests d where d.profile_id=p.profile_id and(d.package_id=p.id or d.package_id is null);
end if;
insert into public.package_events(package_id,status,source_reference,actor_id,occurred_at)values(p.id,p_status,p_source,auth.uid(),p_occurred)returning id into result;
update public.packages set status=p_status,resume_status=case when p_status='exception'then p.status else null end,updated_at=now()where id=p.id;
if p_status in('ready_for_pickup','out_for_delivery','delivered')then insert into public.shipment_release_checks(package_id,event_id,invoice_id,invoice_version,document_count,evidence,actor_id)values(p.id,result,i.id,i.version,docs,p_source,auth.uid());end if;
insert into public.audit_logs(actor_id,entity_type,entity_id,action,before_data,after_data,reason)values(auth.uid(),'package',p.id,'shipment_event',jsonb_build_object('status',p.status),jsonb_build_object('status',p_status,'event_id',result),p_reason);insert into public.event_outbox(event_id)values(result);return result;
end $$;
create or replace function private.correct_package_event(p_package uuid,p_event uuid,p_status text,p_source text,p_reason text,p_explanation text,p_occurred timestamptz) returns uuid language plpgsql security definer set search_path='' as $$
declare target public.package_events; original public.package_events; prior public.package_events; result uuid;
begin
 if not private.has_role(array['owner','operations']) then raise exception 'Access denied';end if;
 perform 1 from public.packages where id=p_package for update;if not found then raise exception 'Package unavailable';end if;
 select * into target from public.package_events where package_id=p_package order by sequence desc limit 1;
 if target.id is null or target.id is distinct from p_event then raise exception 'Latest event changed; refresh';end if;
if target.status not in('pre_alerted','received_us','processing_us','in_transit','arrived_jm')then raise exception 'Use the operational exception workflow after arrival; do not rewrite release history';end if;
 original:=target;
 while original.corrects_event_id is not null loop select * into original from public.package_events where id=original.corrects_event_id;end loop;
 select * into prior from public.package_events where package_id=p_package and sequence<original.sequence order by sequence desc limit 1;
 if p_status is null or p_status not in (original.status,coalesce(prior.status,'pre_alerted')) then raise exception 'Correction may only repair or retract the latest checkpoint';end if;
 if p_occurred is null or not isfinite(p_occurred) or p_occurred>now() or p_occurred<now()-interval '1 year' or (prior.occurred_at is not null and p_occurred<prior.occurred_at) or p_source is null or length(trim(p_source)) not between 5 and 500 or p_reason is null or length(trim(p_reason)) not between 5 and 2000 or p_explanation is null or length(trim(p_explanation)) not between 5 and 1000 then raise exception 'Valid evidence, explanation and effective time required';end if;
 insert into public.package_events(package_id,status,source_reference,actor_id,occurred_at,corrects_event_id,correction_reason)values(p_package,p_status,p_source,auth.uid(),p_occurred,p_event,p_explanation)returning id into result;
 update public.packages set status=p_status,updated_at=now()where id=p_package;
 insert into public.audit_logs(actor_id,entity_type,entity_id,action,before_data,after_data,reason)values(auth.uid(),'package',p_package,'shipment_corrected',jsonb_build_object('event_id',target.id,'status',target.status,'occurred_at',target.occurred_at,'source_reference',target.source_reference),jsonb_build_object('event_id',result,'status',p_status,'occurred_at',p_occurred,'source_reference',p_source),p_reason);
 insert into public.event_outbox(event_id)values(result);return result;
end $$;
alter table public.operational_tasks drop constraint operational_tasks_kind_check;
alter table public.operational_tasks add constraint operational_tasks_kind_check check(kind in('shipment','intake','document','support','invoice'));
create or replace function private.queue_role(p_kind text)returns boolean language sql stable security invoker set search_path='' as $$select case p_kind when 'invoice'then private.has_role(array['owner','finance'])when 'support'then private.has_role(array['owner','support'])when 'document'then private.has_role(array['owner','documents','operations'])when 'shipment'then private.has_role(array['owner','operations'])when 'intake'then private.has_role(array['owner','operations'])else false end$$;
create or replace function private.sync_operational_task()returns trigger language plpgsql security definer set search_path='' as $$declare k text:=tg_argv[0];d jsonb:=to_jsonb(new);s text;ref text;begin
s:=case k when 'invoice'then case when d->>'status'='void'or(d->>'status'='issued'and(d->>'balance_cents')::bigint=0)then 'closed'else 'open'end when 'intake'then case when d->>'package_id'is null then 'open'else 'closed'end when 'support'then case when d->>'status'='open'then 'open'else 'closed'end when 'document'then case when d->>'status'in('approved','waived')then 'closed'else 'open'end else case when d->>'status'in('delivered','returned','cancelled')then 'closed'else 'open'end end;
ref:=case k when 'invoice'then 'Invoice '||(d->>'number')||' · '||(d->>'tracking')when 'intake'then d->>'tracking'when 'shipment'then d->>'carrier_tracking'when 'document'then d->>'document_type'else d->>'subject'end;
insert into public.operational_tasks(kind,source_id,reference,state,opened_at)values(k,new.id,ref,s,new.created_at)on conflict(kind,source_id)do update set reference=excluded.reference,state=excluded.state,opened_at=case when operational_tasks.state='closed'and excluded.state='open'then now()else operational_tasks.opened_at end,version=operational_tasks.version+1,updated_at=now();return new;end$$;
create trigger invoice_queue after insert or update on public.billing_invoices for each row execute function private.sync_operational_task('invoice');
update public.operational_tasks set state='open',version=version+1 where kind='shipment'and state='closed'and source_id in(select id from public.packages where status='arrived_jm');
create or replace function private.manage_operational_task(p_id uuid,p_version integer,p_assignee uuid,p_priority integer,p_due timestamptz,p_reason text) returns void language plpgsql security definer set search_path='' as $$
declare t public.operational_tasks;
begin
 select * into t from public.operational_tasks where id=p_id for update;
 if t.id is null or not private.queue_role(t.kind) then raise exception 'Access denied';end if;
 if t.version is distinct from p_version or t.state<>'open' then raise exception 'Record changed or closed';end if;
 if p_priority is null or p_priority not between 0 and 3 or p_reason is null or length(trim(p_reason)) not between 5 and 2000 or (p_due is not null and not isfinite(p_due)) then raise exception 'Invalid queue update';end if;
 if p_assignee is not null and not exists(select 1 from public.profiles p join public.admin_role_assignments r on r.profile_id=p.id where p.id=p_assignee and p.account_status='active' and (r.role='owner' or (t.kind='invoice' and r.role='finance') or (t.kind='support' and r.role='support') or (t.kind='document' and r.role in ('documents','operations')) or (t.kind in ('shipment','intake') and r.role='operations')))then raise exception 'Assignee requires an active authorized role';end if;
 update public.operational_tasks set assignee_id=p_assignee,priority=p_priority,due_at=p_due,version=version+1,updated_at=now() where id=p_id;
 insert into public.audit_logs(actor_id,entity_type,entity_id,action,before_data,after_data,reason) values(auth.uid(),'queue',p_id,'queue_assigned',jsonb_build_object('assignee_id',t.assignee_id,'priority',t.priority,'due_at',t.due_at),jsonb_build_object('assignee_id',p_assignee,'priority',p_priority,'due_at',p_due),p_reason);
end $$;
create or replace function private.queue_assignees(p_kind text) returns table(id uuid,name text) language sql stable security definer set search_path='' as $$
 select distinct p.id,p.full_name from public.profiles p join public.admin_role_assignments r on r.profile_id=p.id where private.queue_role(p_kind) and p.account_status='active' and (r.role='owner' or (p_kind='invoice' and r.role='finance') or (p_kind='support' and r.role='support') or (p_kind='document' and r.role in ('documents','operations')) or (p_kind in ('shipment','intake') and r.role='operations')) order by p.full_name,p.id
$$;
commit;
